import React from 'react';
import styled from '@emotion/styled';
import { UserCog, LogIn } from 'lucide-react';
import { theme, ThemeToggle } from '@atlantis/shared';
import { LocaleToggle } from '@atlantis/i18n';
import type { Locale } from '@atlantis/i18n';
import { UserMenu } from './UserMenu';
import type { UserMenuUser, UserMenuItem } from './UserMenu';

const Row = styled.div`
  display: flex;
  align-items: center;
  gap: ${theme.spacing.sm};
`;

const IconCircle = styled.button`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  background: transparent;
  border: 1px solid ${theme.colors.border};
  border-radius: 999px;
  color: ${theme.colors.mainTextMuted};
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;

  &:hover {
    color: ${theme.colors.accent};
    border-color: ${theme.colors.accent};
    background: ${theme.colors.sidebarHover};
  }
  &:focus-visible {
    outline: 2px solid ${theme.colors.accent};
    outline-offset: 2px;
  }
`;

const SignInBtn = styled.button`
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 14px;
  background: ${theme.colors.accent};
  border: 1px solid ${theme.colors.accent};
  border-radius: 999px;
  color: #fff;
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeSm};
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
  white-space: nowrap;

  &:hover {
    background: ${theme.colors.accentHover};
    border-color: ${theme.colors.accentHover};
  }
  &:focus-visible {
    outline: 2px solid ${theme.colors.accent};
    outline-offset: 2px;
  }
`;

export interface HeaderRightProps {
  locale: Locale;
  onLocaleChange: (locale: Locale) => void;

  /** Authenticated user. When omitted, a Sign in button renders instead. */
  user?: UserMenuUser;
  /** Rows shown in the UserMenu dropdown. Required when `user` is present. */
  userMenuItems?: UserMenuItem[];
  /** If provided, renders a cog icon button for opening preferences/settings. */
  onPreferences?: () => void;
  /** If provided (and no user), renders a "Sign in" button that calls this handler. */
  onSignIn?: () => void;
  /** Label for the Sign in button (default: "Sign in"). */
  signInLabel?: string;

  /** Slot before the locale toggle — e.g. <LiveIndicator count={9} /> */
  before?: React.ReactNode;
  /** Slot after the user menu — e.g. extra app-specific chrome */
  after?: React.ReactNode;
}

/**
 * Standard right-hand side of the app top bar: locale toggle, theme toggle,
 * optional preferences cog, and either a UserMenu (authenticated) or a
 * Sign in button (unauthenticated).
 *
 * Used by both the home screen and every remote app's Layout so headers
 * stay visually identical across the product.
 */
export function HeaderRight({
  locale,
  onLocaleChange,
  user,
  userMenuItems = [],
  onPreferences,
  onSignIn,
  signInLabel = 'Sign in',
  before,
  after,
}: HeaderRightProps) {
  return (
    <Row>
      {before}
      <LocaleToggle locale={locale} onChange={onLocaleChange} />
      <ThemeToggle />
      {onPreferences && (
        <IconCircle onClick={onPreferences} aria-label="User preferences" title="Preferences">
          <UserCog size={16} />
        </IconCircle>
      )}
      {user ? (
        <UserMenu user={user} items={userMenuItems} />
      ) : onSignIn ? (
        <SignInBtn onClick={onSignIn} aria-label={signInLabel}>
          <LogIn size={14} />
          {signInLabel}
        </SignInBtn>
      ) : null}
      {after}
    </Row>
  );
}
