import { useState, useEffect, useCallback, useMemo } from 'react';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme, navigateTo } from '@atlantis/shared';
import { createT } from '@atlantis/i18n';
import SHELL_KEYS from '../translations';
import { cachedFetch } from './cachedFetch';

// Lisbon coordinates (free, no API key needed)
const LAT = 38.7223;
const LON = -9.1393;

interface WeatherData {
  current: {
    temperature_2m: number;
    relative_humidity_2m: number;
    weather_code: number;
    wind_speed_10m: number;
    is_day: number;
  };
}

const WMO_ICONS: Record<number, string> = {
  0: '☀️', 1: '🌤️', 2: '⛅', 3: '☁️',
  45: '🌫️', 48: '🌫️',
  51: '🌦️', 53: '🌦️', 55: '🌧️',
  61: '🌧️', 63: '🌧️', 65: '🌧️',
  71: '🌨️', 73: '🌨️', 75: '🌨️',
  77: '🌨️',
  80: '🌦️', 81: '🌧️', 82: '🌧️',
  85: '🌨️', 86: '🌨️',
  95: '⛈️', 96: '⛈️', 99: '⛈️',
};

const WMO_DESC_EN: Record<number, string> = {
  0: 'Clear sky', 1: 'Mainly clear', 2: 'Partly cloudy', 3: 'Overcast',
  45: 'Foggy', 48: 'Rime fog',
  51: 'Light drizzle', 53: 'Drizzle', 55: 'Dense drizzle',
  61: 'Light rain', 63: 'Rain', 65: 'Heavy rain',
  71: 'Light snow', 73: 'Snow', 75: 'Heavy snow', 77: 'Snow grains',
  80: 'Light showers', 81: 'Showers', 82: 'Heavy showers',
  85: 'Light snow showers', 86: 'Snow showers',
  95: 'Thunderstorm', 96: 'Hail storm', 99: 'Severe hail storm',
};

const WMO_DESC_PT: Record<number, string> = {
  0: 'Céu limpo', 1: 'Pouco nublado', 2: 'Parcialmente nublado', 3: 'Encoberto',
  45: 'Nevoeiro', 48: 'Nevoeiro gelado',
  51: 'Chuviscos leves', 53: 'Chuviscos', 55: 'Chuviscos densos',
  61: 'Chuva fraca', 63: 'Chuva', 65: 'Chuva forte',
  71: 'Neve fraca', 73: 'Neve', 75: 'Neve forte', 77: 'Grãos de neve',
  80: 'Aguaceiros fracos', 81: 'Aguaceiros', 82: 'Aguaceiros fortes',
  85: 'Neve fraca', 86: 'Neve forte',
  95: 'Trovoada', 96: 'Granizo', 99: 'Granizo forte',
};

function getWeatherIcon(code: number): string {
  return WMO_ICONS[code] ?? '🌡️';
}

function getWeatherDesc(code: number, locale: string): string {
  const table = locale === 'pt' ? WMO_DESC_PT : WMO_DESC_EN;
  return table[code] ?? (locale === 'pt' ? 'Desconhecido' : 'Unknown');
}

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
`;

const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  height: 100%;
  animation: ${fadeIn} 0.3s ease both;
  cursor: pointer;
  border-radius: ${theme.borderRadius.sm};
  transition: background 0.15s;

  &:hover {
    background: ${theme.colors.sidebarHover};
  }
  &:focus-visible {
    outline: 2px solid ${theme.colors.accent};
    outline-offset: 2px;
  }
`;

const OpenHint = styled.div`
  font-size: 10px;
  font-family: ${theme.typography.fontFamilyMono};
  color: ${theme.colors.mainTextMuted};
  opacity: 0;
  transition: opacity 0.15s;
  margin-top: 6px;
  letter-spacing: 0.04em;

  ${Wrapper}:hover & {
    opacity: 0.7;
  }
`;

const Location = styled.div`
  font-size: 11px;
  font-weight: 600;
  font-family: ${theme.typography.fontFamilyMono};
  color: ${theme.colors.mainTextMuted};
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 12px;
`;

const MainRow = styled.div`
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
`;

const BigIcon = styled.div`
  font-size: 40px;
  line-height: 1;
`;

const TempBlock = styled.div`
  display: flex;
  flex-direction: column;
`;

const Temp = styled.div`
  font-size: 32px;
  font-weight: 700;
  font-family: ${theme.typography.fontFamily};
  color: ${theme.colors.mainText};
  line-height: 1;
  letter-spacing: -0.03em;
`;

const Condition = styled.div`
  font-size: 13px;
  color: ${theme.colors.mainTextMuted};
  font-family: ${theme.typography.fontFamily};
  margin-top: 2px;
`;

const Stats = styled.div`
  display: flex;
  gap: 16px;
  margin-top: auto;
  padding-top: 8px;
`;

const StatItem = styled.div`
  font-size: 11px;
  font-family: ${theme.typography.fontFamilyMono};
  color: ${theme.colors.mainTextMuted};
  span { color: ${theme.colors.mainText}; font-weight: 600; }
`;

const Placeholder = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 1;
  font-size: 12px;
  color: ${theme.colors.mainTextMuted};
  opacity: 0.5;
`;

interface WeatherWidgetProps {
  locale: string;
}

export function WeatherWidget({ locale }: WeatherWidgetProps) {
  const t = useMemo(() => createT(locale === 'pt' ? 'pt' : 'en', SHELL_KEYS), [locale]);
  const [data, setData] = useState<WeatherData | null>(null);

  const fetchWeather = useCallback(async () => {
    const result = await cachedFetch<WeatherData>(
      `https://api.open-meteo.com/v1/forecast?latitude=${LAT}&longitude=${LON}&current=temperature_2m,relative_humidity_2m,weather_code,wind_speed_10m,is_day`,
      'weather-lisbon'
    );
    if (result) setData(result);
  }, []);

  useEffect(() => {
    fetchWeather();
    const id = setInterval(fetchWeather, 15 * 60 * 1000);
    return () => clearInterval(id);
  }, [fetchWeather]);

  const openInEarth = () => navigateTo('earth', { placeId: 'lisbon' });
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openInEarth(); }
  };

  if (!data) {
    return (
      <Wrapper role="link" tabIndex={0} onClick={openInEarth} onKeyDown={onKeyDown}>
        <Placeholder>{t('loading')}</Placeholder>
      </Wrapper>
    );
  }

  const { temperature_2m, relative_humidity_2m, weather_code, wind_speed_10m } = data.current;

  return (
    <Wrapper role="link" tabIndex={0} onClick={openInEarth} onKeyDown={onKeyDown}>
      <Location>🌤️ {t('weather.city.lisbon')}</Location>
      <MainRow>
        <BigIcon>{getWeatherIcon(weather_code)}</BigIcon>
        <TempBlock>
          <Temp>{Math.round(temperature_2m)}°</Temp>
          <Condition>{getWeatherDesc(weather_code, locale)}</Condition>
        </TempBlock>
      </MainRow>
      <Stats>
        <StatItem>{t('weather.humidity')} <span>{relative_humidity_2m}%</span></StatItem>
        <StatItem>{t('weather.wind')} <span>{Math.round(wind_speed_10m)} km/h</span></StatItem>
      </Stats>
      <OpenHint>{t('weather.openInEarth')}</OpenHint>
    </Wrapper>
  );
}
