const RECENT_APPS_KEY = 'shell:recent';
const PINNED_APPS_KEY = 'shell:pinned';
const RECENT_MAX = 8;

function parseIds(raw: string | null): string[] {
  try { return JSON.parse(raw ?? '[]'); } catch { return []; }
}


const NEEDS_AUTH = new Set(
  APP_CONFIG.filter((a) => a.needsAuth).map((a) => a.id)
);

const MOCK_USER = process.env.MOCK_USER === 'true' ? {
  id: 'mock-user',
  email: 'dev@atlantis.local',
  user_metadata: { full_name: 'Dev User', avatar_url: '' },
} as unknown as User : null;
const TMDB_API_KEY = process.env.TMDB_API_KEY || '';

const PALETTE_APPS: AppEntry[] = APP_CONFIG
  .filter((app) => app.enabled)
  .map(({ id, label, hash, icon, description, color, category }) => ({
    id, label, hash, icon, description, color, category,
  }));

export default function App() {
  const [activeAppId,   setActiveAppId]   = useState(() => getAppFromHash(window.location.hash));
  const [recentApps,    setRecentApps]    = useState<string[]>([]);
  const [pinnedApps,    setPinnedApps]    = useState<string[]>([]);
  const [user,          setUser]          = useState<User | null>(MOCK_USER);
  const [authReady,     setAuthReady]     = useState(!!MOCK_USER);
  const [showPalette,   setShowPalette]   = useState(false);
  const [showProfile,   setShowProfile]   = useState(false);
  const [locale, setLocale]              = useLocale();

  // Subscribe to Supabase auth state and switch storage provider accordingly
  useEffect(() => {
    if (MOCK_USER) return; // skip Supabase in mock mode
    supabase.auth.getSession().then(({ data }) => {
      const u = data.session?.user ?? null;
      setUser(u);
      setStorageProvider(u ? supabaseProvider : null);
      setAuthReady(true);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      const u = session?.user ?? null;
      setUser(u);
      setStorageProvider(u ? supabaseProvider : null);
    });
    return () => subscription.unsubscribe();
  }, []);

  // Load persisted state from IDB on mount
  useEffect(() => {
    getSetting(RECENT_APPS_KEY).then((v) => setRecentApps(parseIds(v)));
    getSetting(PINNED_APPS_KEY).then((v) => setPinnedApps(parseIds(v)));
  }, []);

  // Cmd+K / Ctrl+K → open command palette
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setShowPalette((v) => !v);
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, []);

  useEffect(() => {
    const onHashChange = () => setActiveAppId(getAppFromHash(window.location.hash));
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);

  // Track recently used whenever activeAppId changes (skip 'home')
  useEffect(() => {
    if (!activeAppId || activeAppId === 'home') return;
    setRecentApps((prev) => {
      const next = [activeAppId, ...prev.filter((id) => id !== activeAppId)].slice(0, RECENT_MAX);
      putSetting(RECENT_APPS_KEY, JSON.stringify(next));
      return next;
    });
  }, [activeAppId]);

  const handleNavigate = useCallback((hash: string) => {
    window.location.hash = hash;
    setShowPalette(false);
  }, []);

  const handleTogglePin = (appId: string) => {
    setPinnedApps((prev) => {
      const next = prev.includes(appId) ? prev.filter((id) => id !== appId) : [...prev, appId];
      putSetting(PINNED_APPS_KEY, JSON.stringify(next));
      return next;
    });
  };

  const handleMovePinned = (appId: string, direction: -1 | 1) => {
    setPinnedApps((prev) => {
      const idx = prev.indexOf(appId);
      if (idx < 0) return prev;
      const newIdx = idx + direction;
      if (newIdx < 0 || newIdx >= prev.length) return prev;
      const next = [...prev];
      [next[idx], next[newIdx]] = [next[newIdx], next[idx]];
      putSetting(PINNED_APPS_KEY, JSON.stringify(next));
      return next;
    });
  };

  const appLabel = APP_CONFIG.find((a) => a.id === activeAppId)?.label ?? activeAppId;

  // Block access to protected apps until auth is ready, then gate if unauthenticated
  if (!authReady) return <ThemeProvider><LoadingScreen /></ThemeProvider>;

  if (NEEDS_AUTH.has(activeAppId) && !user) {
    return (
      <ThemeProvider>
        <AuthGate
          appLabel={appLabel}
          onBack={() => { window.location.hash = '#/home'; }}
        />
      </ThemeProvider>
    );
  }

  const liveCount = LIVE_FEED_COUNT[activeAppId];

  // Unified header chrome — identical layout on home and in every remote app.
  // See `@atlantis/ui` → HeaderRight + UserMenu + docs/ui.md.
  const topBarRight = (
    <HeaderRight
      locale={locale}
      onLocaleChange={setLocale}
      before={liveCount != null ? <LiveIndicator count={liveCount} /> : undefined}
      onPreferences={() => setShowProfile(true)}
      user={user ? {
        name: user.user_metadata?.full_name,
        email: user.email ?? '',
        avatarUrl: user.user_metadata?.avatar_url,
      } : undefined}
      userMenuItems={user ? [
        { label: 'Settings', icon: <Settings size={14} />, onClick: () => { window.location.hash = '#/settings'; } },
        { label: 'Sign out', icon: <LogOut size={14} />, onClick: signOut, danger: true },
      ] : []}
      onSignIn={() => { window.location.hash = '#/home'; /* AuthGate handles the flow */ }}
    />
  );

  const palette = showPalette && (
    <CommandPalette
      apps={PALETTE_APPS}
      recentIds={recentApps}
      onNavigate={handleNavigate}
      onClose={() => setShowPalette(false)}
    />
  );

  const profileModal = (
    <ProfileModal
      open={showProfile}
      onClose={() => setShowProfile(false)}
      locale={locale}
    />
  );

  if (activeAppId === 'home') {
    return (
      <ThemeProvider>
        <FadeWrapper key="home">
          <HomeScreen
            apps={APPS}
            recentAppIds={recentApps}
            pinnedAppIds={pinnedApps}
            onTogglePin={handleTogglePin}
            onMovePinned={handleMovePinned}
            onSelect={(app) => { window.location.hash = app.hash; }}
            user={user ? { name: user.user_metadata?.full_name, email: user.email ?? '', avatarUrl: user.user_metadata?.avatar_url } : null}
            onSignOut={signOut}
            onPreferences={() => setShowProfile(true)}
          />
        </FadeWrapper>
        {palette}
        {profileModal}
      </ThemeProvider>
    );
  }

  return (
    <ThemeProvider>
      <RemoteErrorBoundary name={activeAppId}>
        <Suspense fallback={<LoadingScreen />}>
          <FadeWrapper key={activeAppId}>
            {activeAppId === 'earth'        && <EarthApp        topBarRight={topBarRight} />}
            {activeAppId === 'markdown'     && <MarkdownApp     topBarRight={topBarRight} />}
            {activeAppId === 'techscope'    && <TechScopeApp    topBarRight={topBarRight} />}
            {activeAppId === 'citypulse'    && <CityPulseApp    topBarRight={topBarRight} />}
            {activeAppId === 'cosmos'       && <CosmosApp       topBarRight={topBarRight} />}
            {activeAppId === 'stockpulse'   && <StockPulseApp   topBarRight={topBarRight} />}
            {activeAppId === 'pad'          && <PadApp           topBarRight={topBarRight} />}
            {activeAppId === 'regexlab'     && <RegexLabApp     topBarRight={topBarRight} />}
            {activeAppId === 'jsonexplorer' && <JsonExplorerApp topBarRight={topBarRight} />}
            {activeAppId === 'codediff'     && <CodeDiffApp     topBarRight={topBarRight} />}
            {activeAppId === 'playground'   && <JsFiddleApp     topBarRight={topBarRight} />}
            {activeAppId === 'jwtinspector' && <JwtInspectorApp topBarRight={topBarRight} />}
            {activeAppId === 'colorlab'     && <ColorLabApp     topBarRight={topBarRight} />}
            {activeAppId === 'cronbuilder'  && <CronBuilderApp  topBarRight={topBarRight} />}
            {activeAppId === 'csvexplorer'  && <CsvExplorerApp  topBarRight={topBarRight} />}
            {activeAppId === 'chartbuilder' && <ChartBuilderApp topBarRight={topBarRight} />}
            {activeAppId === 'school'       && <EscolaApp       topBarRight={topBarRight} />}
            {activeAppId === 'games'        && <GamesApp        topBarRight={topBarRight} isAuthenticated={!!user} />}
            {activeAppId === 'weather'      && <WeatherApp      topBarRight={topBarRight} />}
            {activeAppId === 'apiexplorer'  && <ApiExplorerApp  topBarRight={topBarRight} />}
            {activeAppId === 'movies'       && <MoviesApp       topBarRight={topBarRight} apiKey={TMDB_API_KEY} />}
            {activeAppId === 'promptlab'   && <PromptLabApp    topBarRight={topBarRight} />}
            {activeAppId === 'imagegen'    && <ImageGenApp     topBarRight={topBarRight} />}
            {activeAppId === 'settings'   && (
              <Layout title="Settings" sidebar={null} topBarRight={topBarRight}>
                <SettingsPage lang={locale === 'pt' ? 'pt' : 'en'} />
              </Layout>
            )}
          </FadeWrapper>
        </Suspense>
      </RemoteErrorBoundary>
      {palette}
      {profileModal}
    </ThemeProvider>
  );
}
