/**
 * Central configuration for all apps.
 * Edit apps.config.json to add/remove apps or change their properties.
 * Set `enabled: false` to hide an app from the home screen and navigation.
 */
import appsData from './apps.config.json';
import type { Interest } from '@atlantis/shared';

export interface AppConfig {
  id: string;
  port: number;
  label: string;
  labelPt?: string;
  hash: string;
  icon: string;
  description: string;
  descriptionPt?: string;
  color: string;
  enabled: boolean;
  category: string;
  needsAuth: boolean;
  suite?: string;
  homeHidden?: boolean;
  /** If set, the app is hidden when `hasInterests(profile)` is true and
   *  `profile.interests` doesn't include this tag. Apps without `interest`
   *  (tools, utilities) are always shown regardless of selected interests.
   *
   *  Note: `profile.ageMode` is NOT used to hide apps — apps that need to
   *  respect age mode must adjust their own content internally. */
  interest?: Interest;
}

// JSON imports are typed as `string`, which doesn't narrow into the `Interest`
// or `AgeMode` unions. Cast through `unknown` — we trust the JSON matches the
// AppConfig shape and `normalize()` in profile.ts would reject bad values at runtime.
const APPS: AppConfig[] = appsData as unknown as AppConfig[];

export default APPS;
